SDTExtrusion
{        
//	SDTExtrusionItem
//        Where ExtrusionId > 0
//        where ExtrusionOperadorId = &OperadorId and ExtrusionEstado in (EstadoExtrusion.Programada) when &Asignado = true and &OperadorId > 0
